            Transform local = new Transform(
                node.getFloatAttribute("x", 0f),
                node.getFloatAttribute("y", 0f),
                node.getFloatAttribute("rotation", 0f),
                node.getFloatAttribute("scaleX", 1f),
                node.getFloatAttribute("scaleY", 1f)
            );
