            }

            Array<XmlReader.Element> topLevelNodes = scene.getChildrenByName("node");
            if (scene.getChildCount() != 1 || topLevelNodes.size != 1) {
                throw new IllegalArgumentException("<scene> must contain exactly one top-level <node>.");
