    private static final Transform IDENTITY = new Transform(0f, 0f, 0f, 1f, 1f);

    private final float x;
    private final float y;
    private final float rotationDeg;
    private final float scaleX;
    private final float scaleY;

    private Transform(float x, float y, float rotationDeg, float scaleX, float scaleY) {
        this.x = x;
        this.y = y;
        this.rotationDeg = rotationDeg;
        this.scaleX = scaleX;
        this.scaleY = scaleY;
    }

    private Transform toWorld(Transform parentWorld) {
        float localScaledX = x * parentWorld.scaleX;
        float localScaledY = y * parentWorld.scaleY;
        float cos = MathUtils.cosDeg(parentWorld.rotationDeg);
        float sin = MathUtils.sinDeg(parentWorld.rotationDeg);
        float rotatedX = localScaledX * cos - localScaledY * sin;
        float rotatedY = localScaledX * sin + localScaledY * cos;

        return new Transform(
            parentWorld.x + rotatedX,
            parentWorld.y + rotatedY,
            parentWorld.rotationDeg + rotationDeg,
            parentWorld.scaleX * scaleX,
            parentWorld.scaleY * scaleY
        );
    }
}

